import{_ as t,o,c as a,a6 as s}from"./chunks/framework.BJFjZBwW.js";const p=JSON.parse('{"title":"Actuators","description":"","frontmatter":{},"headers":[],"relativePath":"use/actuators.md","filePath":"use/actuators.md","lastUpdated":1707950829000}'),i={name:"use/actuators.md"};function n(r,e,l,h,d,c){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="actuators" tabindex="-1">Actuators <a class="header-anchor" href="#actuators" aria-label="Permalink to &quot;Actuators&quot;">​</a></h1><h2 id="on-off-functionality" tabindex="-1">ON/OFF Functionality <a class="header-anchor" href="#on-off-functionality" aria-label="Permalink to &quot;ON/OFF Functionality&quot;">​</a></h2><p>The ON/OFF module of the OpenMQTTGateway provides you with the capability to control actuators, such as relays or LEDs, by assigning a HIGH or LOW value to a specific PIN through MQTT topics. For instance, you might connect a transistor to power a relay or an LED to the PIN.</p><p>To operate the default GPIO, identified as ACTUATOR_ONOFF_GPIO, you&#39;ll need to issue certain commands which comply with the JSON receiving format.</p><h3 id="standard-on-off-control" tabindex="-1">Standard ON/OFF control <a class="header-anchor" href="#standard-on-off-control" aria-label="Permalink to &quot;Standard ON/OFF control&quot;">​</a></h3><p>The OFF command can be executed as follows: <code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoONOFF -m &#39;{&quot;cmd&quot;:0}&#39;</code></p><p>For the ON command, use: <code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoONOFF -m &#39;{&quot;cmd&quot;:1}&#39;</code></p><p>You can also specify the GPIO number that you wish to control: <code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoONOFF -m &#39;{&quot;gpio&quot;:15,&quot;cmd&quot;:1}&#39;</code></p><p>The status of the actuator will be published to the topic below every 2 minutes or upon state change. <code>home/OpenMQTTGateway/ONOFFtoMQTT &#39;{&quot;cmd&quot;:0}&#39;</code></p><p>In the case of the simple receiving format, the commands can be executed as follows: OFF command: <code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoONOFF/setOFF -m 15</code> ON command: <code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoONOFF/setON -m 15</code></p><h3 id="pulse-control-for-short-activations" tabindex="-1">Pulse control for short activations <a class="header-anchor" href="#pulse-control-for-short-activations" aria-label="Permalink to &quot;Pulse control for short activations&quot;">​</a></h3><p>Additionally, the module also supports short activations, during which the PIN changes state for just half a second. This can be particularly useful when operating a relay board to trigger a step relay, thus allowing your home automation system to function as an auxiliary switch, without interfering with the existing switches in your house.</p><p>This functionality is available only through the JSON receiving format.</p><p>To switch ON for half a second before reverting to OFF: <code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoONOFF -m &#39;{&quot;gpio&quot;:15,&quot;cmd&quot;:&quot;high_pulse&quot;}&#39;</code></p><p>To switch OFF for half a second before reverting to ON: <code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoONOFF -m &#39;{&quot;gpio&quot;:15,&quot;cmd&quot;:&quot;low_pulse}&#39;</code></p><p>If you need to specify an activation duration other than half a second, include the pulse_length parameter along with the duration in milliseconds (ms).</p><p>To switch ON for 25 ms before reverting to OFF: <code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoONOFF -m &#39;{&quot;gpio&quot;:15,&quot;cmd&quot;:&quot;high_pulse&quot;,&quot;pulse_length&quot;:25}&#39;</code></p><p>To switch OFF for 25 ms before reverting to ON: <code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoONOFF -m &#39;{&quot;gpio&quot;:15,&quot;cmd&quot;:&quot;low_pulse&quot;,&quot;pulse_length&quot;:25}&#39;</code></p><p>Recovery Functionality (ESP32 only) In the event of power loss, by default, the module will record the last known state of the actuator and attempt to revert to this state upon restarting. For example, if a relay was ON at the time of a power outage, the firmware will attempt to switch the relay ON again once power is restored.</p><p>If you prefer to disable this functionality, you can set the macro USE_LAST_STATE_ON_RESTART to false during the build time. Alternatively, you can issue the following command at runtime: <code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoONOFF/config -m &#39;{&quot;uselaststate&quot;:false,&quot;save&quot;:true}&#39;</code></p><h2 id="fastled" tabindex="-1">FASTLED <a class="header-anchor" href="#fastled" aria-label="Permalink to &quot;FASTLED&quot;">​</a></h2><h3 id="the-fastled-module-support-2-different-operation-modes" tabindex="-1">The FASTLED module support 2 different operation modes <a class="header-anchor" href="#the-fastled-module-support-2-different-operation-modes" aria-label="Permalink to &quot;The FASTLED module support 2 different operation modes&quot;">​</a></h3><ol><li>control one specific RGB LED</li></ol><ul><li>Set color</li><li>Set blink</li></ul><ol start="2"><li>Start fire animation (Fire2012)</li></ol><h3 id="hardware-wiring" tabindex="-1">Hardware wiring <a class="header-anchor" href="#hardware-wiring" aria-label="Permalink to &quot;Hardware wiring&quot;">​</a></h3><p>Theoretically it should be possible to use every free IO pin. But after some tests only pin D2 works at WEMOS D1. Other platforms can work. The default setting use NEOPIXEL (WS2812B). The simplest wiring is direct connect D2 to data pin of LED stripe and connect VCC/GND to power source. You should also add a capacitor.</p><h2 id="pwm" tabindex="-1">PWM <a class="header-anchor" href="#pwm" aria-label="Permalink to &quot;PWM&quot;">​</a></h2><p>This module allows control over PWM outputs. It&#39;s primary use is for controlling LEDs, but it should be equally at home controlling anything that&#39;s controlled using PWM. E.g. LEDs, servos, PC fans. You would typically connect a PWM output to a transistor or MOSFET to allow control over higher power devices.</p><ul><li>JSON message format allows you to set any or all channels in a single message.</li><li>Each channel can be set to smoothly transition from its current setting to the new setting over a specified number of seconds.</li><li>Each channel can be calibrated with min and max settings, as well as a gamma curve.</li></ul><h3 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h3><p>In order to use the PWM actuator, you need to configure which pins the PWM output channels will be connected to. There are a couple of <code>#defines that achieve this. They can be defined in the </code>build_flags<code>section of the env, or by directly editing</code>config_PWM.h`.</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> PWM_CHANNEL_NAMES</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;r&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;g&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;b&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;w0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;w1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> PWM_CHANNEL_PINS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">25</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,  </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">33</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,  </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,   </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">23</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,   </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">22</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><code>PWM_CHANNEL_NAMES</code> lists the names that you would like to assign to each channel, and determines the number of channels. <code>PWM_CHANNEL_PINS</code> lists the corresponding output pins that the channels will be connected to. The number of entries in <code>PWM_CHANNEL_PINS</code> must exactly match the number of entries in <code>PWM_CHANNEL_NAMES</code>.</p><h3 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h3><h4 id="set" tabindex="-1">Set <a class="header-anchor" href="#set" aria-label="Permalink to &quot;Set&quot;">​</a></h4><p><code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoPWM/set -m &#39;{&quot;r&quot;:0.5,&quot;g&quot;:0.2,&quot;b&quot;:1,&quot;fade&quot;:10.0}&#39;</code></p><p>This example sets new values for the channels named <code>r</code>, <code>g</code>, and <code>b</code>. These channels will transition from their current values to the new values over 10s.</p><h4 id="calibrate" tabindex="-1">Calibrate <a class="header-anchor" href="#calibrate" aria-label="Permalink to &quot;Calibrate&quot;">​</a></h4><p>Calibration allows that min and max levels to be configured for each channel, so that the full 0-1 range of values that can be specified with the <code>set</code> command actually do things.</p><p><code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoPWM/calibrate -m &#39;{&quot;min-r&quot;:0.01,&quot;max-r&quot;:1.0,&quot;gamma-r&quot;:2.5}&#39;</code></p><p>This example calibrates the channel named <code>r</code>. After this calibration, if you set the <code>r</code> channel to 0.0, it will be remapped to 0.01 internally. Also, the gamma curve for this channel will be set to 2.5. This means that input values are raised to the power 2.5 internally. This can be used to improve the linearity of inputs.</p><h2 id="somfy-rts" tabindex="-1">Somfy RTS <a class="header-anchor" href="#somfy-rts" aria-label="Permalink to &quot;Somfy RTS&quot;">​</a></h2><p>This actuator allows to control Somfy RTS devices.</p><h3 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h3><p>Before the module can be used, virtual Somfy RTS remotes must be created. This is done in <code>config_Somfy.h</code>.</p><p><code>SOMFY_REMOTE_NUM</code> must be set to the number of virtual Somfy RTS remotes you want to have. Then create for each of the virtual Somfy RTS remotes a unique 3-byte code and add them to <code>somfyRemotes</code>. After a remote is setup, the order and codes should not be changed, else the setup process for all remotes have to be repeated. Adding new codes at the end of the list is no problem. Example of three virtual Somfy RTS remote codes:</p><div class="language-C vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">C</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> uint32_t</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> somfyRemotes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[SOMFY_REMOTE_NUM] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5184c8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ba24d0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">b77753</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Next the virtual Somfy RTS remotes must be paired with the Somfy RTS devices you want to control. The next section describes how the PROG command/button of the virtual remote can be used. Use the manual of the device you want to control for instructions on how to pair the virtual remote with the device.</p><h3 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h3><p>Commands must be send to the <code>commands/MQTTtoSomfy</code> subtopic. Only json messages are supported. The json message must contain two properties:</p><ul><li>remote: the index of the remote which is used to send the command (index start at zero)</li><li>command: the command which should be send with the remote as string, see <a href="https://github.com/Legion2/Somfy_Remote_Lib#available-commands" target="_blank" rel="noreferrer">table of command names</a>.</li></ul><p>Optionally it can contain the following property:</p><ul><li>repeat: the number how often the command is repeated, default 4. Should be used to simulate long button presses, by increasing the repeat number, e.g. 20.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The middle button on physical Somfy RTS Remote controls is called &quot;My&quot;.</p></div><p>The frequency key is optional, if not set the gateway will use the default frequency defined by MQTTtoRF command at runtime or <code>RF_FREQUENCY</code> at buildtime.</p><p>Send PROG command with remote 0:</p><p><code>mosquitto_pub -t home/OpenMQTTGateway_Somfy/commands/MQTTtoSomfy -m &#39;{&quot;remote&quot;:0,&quot;command&quot;:&quot;Prog&quot;,&quot;frequency&quot;:433.42}&#39;</code></p><p>Send Up command with remote 1:</p><p><code>mosquitto_pub -t home/OpenMQTTGateway_Somfy/commands/MQTTtoSomfy -m &#39;{&quot;remote&quot;:1,&quot;command&quot;:&quot;Up&quot;,&quot;frequency&quot;:433.42}&#39;</code></p>',60)])])}const m=t(i,[["render",n]]);export{p as __pageData,m as default};
